INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','README.md','9f9fa8dafe744832be1be9175c989864c97b21681abca3b29623eb92df2faf8a','# Synthetic receipt service
Requests with the same key reuse the stored receipt.
The route calls storage. No runtime results are claimed.
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','app/api.py','d8a5646044b772b88b788b80c12facea922c8dde808c90cc638ed3b026b7319e','from .storage import save_receipt

def handle(key, store):
    return save_receipt(key, store)
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','app/storage.py','623c500827623616039a3bf42f8ad3cbb4a21056ff551d817790570b473722e9','def save_receipt(key, store):
    """Reuse a stored receipt to avoid duplicate writes."""
    if key in store:
        return store[key]
    store[key] = "done"
    return store[key]
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','docs/scope.md','86be5bd7a59b4b79cc2eb5a4ac4ddb935fdcdbed4d786117152f63d372bd97bd','# Receipt teaching fixture
## Sources
Only the fixed source revision is cited; a source reference is not a performance measurement.
## Limits
There is no durable database and no benchmark in this teaching fixture.
## Budget
Return at most five complete passages. Omit a whole passage when it does not fit the quote budget.
## Verification
A test file contains source assertions. This document does not report executing those tests.
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','rules.py','1b4a6dec8da27df457bdd52d383cb735bc5a91b8bbbacba34f2f395be4d81500','def choose_mode(semantic_configured):
    return "hybrid" if semantic_configured else "keyword"

def needs_rebuild(saved_identity, current_identity):
    return saved_identity != current_identity
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','serialize.py','011771aa01f1882f51745bcdcf1527d6a089a37582bde68f32e40ce950d2fe20','import json

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))

def payload_digest(value):
    from hashlib import sha256
    return sha256(canonical(value).encode("utf-8")).hexdigest()
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','tests/test_rules.py','9bf93c8ef6f26e5efb3e91b694354b582e822ff60972868d9a87675c956e2455','from rules import choose_mode, needs_rebuild

def test_disabled_semantics():
    assert choose_mode(False) == "keyword"

def test_identity_change():
    assert needs_rebuild("old", "new")
    assert not needs_rebuild("same", "same")
');
INSERT INTO "v3_project_files" VALUES('snapshot-e8d41f75111c4065ad9ddf32a17001e9','tests/test_storage.py','4c98e8a00538e9be302d2cf7088c8119f6652b48dd3a9d9f02cc70e3f73251a6','from app.storage import save_receipt

def test_duplicate():
    store = {}
    assert save_receipt("x", store) == save_receipt("x", store)
');
