INSERT INTO "v3_public_versions" VALUES('knowledge-125713161f37fa621f2b85a24b5ec75d410d5a33501c9f0bbb7e5bfbec077300','doc-ast','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"ast.parse将Python文本解析为语法树，可提取函数、类、参数和行位置，不需要导入并执行代码。静态分析能解析部分导入与直接调用；对象动态绑定、反射或运行时修改不能只按名字猜。本项目把这些边标为静态可解析引用，不能据此声称函数实际执行过，测试文件存在也不代表测试通过。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-ast","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://docs.python.org/3.12/library/ast.html","source_version":"Python 3.12 documentation","tags":["AST","Python","符号","静态","源码"],"technical_doc_id":null,"title":"AST符号与静态分析边界","updated_at":"2026-10-20"}','125713161f37fa621f2b85a24b5ec75d410d5a33501c9f0bbb7e5bfbec077300','ade73216cdfb5f704742f7822be1ee9611a1c8421d66b1a48fb83ac92f804004');
INSERT INTO "v3_public_versions" VALUES('knowledge-981bfd3c18487ed070b4091db642cad6756971b60228073f946586b56e1fac3e','doc-checkpoint','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"Checkpoint保存一次线程运行的状态，便于继续对话、中断恢复和人工交互。Store保存跨线程使用的业务信息，例如用户偏好。内存Saver在进程退出后会丢失，持久化需要相应存储。本项目的业务版本、岗位档案与执行检查点是不同数据，不能把保存聊天记录说成实现了全部恢复机制。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-checkpoint","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://docs.langchain.com/oss/python/langgraph/persistence","source_version":"LangGraph rolling docs; checked 2026-10-20","tags":["LangGraph","checkpoint","state","memory","状态","恢复"],"technical_doc_id":null,"title":"Checkpoint与长期记忆","updated_at":"2026-10-20"}','981bfd3c18487ed070b4091db642cad6756971b60228073f946586b56e1fac3e','f46d4eb04ed52c865d7a95941410c6091499f49921f88483cd55bab1cd39d8f5');
INSERT INTO "v3_public_versions" VALUES('knowledge-c3528ee033271edcd1a9637ad86deae27568f09a6f08c5ec22c1414a6c74fc1f','doc-citation','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"内容哈希便于核对文本身份，但哈希一致不能证明真实经历或语义结论。本项目的代码引用绑定owner、项目、快照、commit、路径、行范围与原文；引用旧版时不能悄悄指向最新文件。索引重建可替换派生结构，历史源码快照保持不变；删除来源后，旧引用应不可解析，而非回退到相似资料。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-citation","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://docs.python.org/3.12/library/hashlib.html","source_version":"Python 3.12 documentation","tags":["SHA256","引用","commit","快照","hash"],"technical_doc_id":null,"title":"快照引用、哈希与版本","updated_at":"2026-10-20"}','c3528ee033271edcd1a9637ad86deae27568f09a6f08c5ec22c1414a6c74fc1f','8491cd3e56e0276fee498ce58103a7254e22317af29ff1d9af61b8845aadb774');
INSERT INTO "v3_public_versions" VALUES('knowledge-98ecb016acfef596ca7c8d7d9f0737df8696ef3ff9af6ad9ce0f523ab64e0278','doc-idempotency','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"消费组的待确认消息需要与业务完成状态区分。本项目采用的可靠性原则是：相同逻辑操作使用稳定请求键，先查回执；外部请求超时不等于操作失败。数据库状态无法和任意外部服务形成一个本地事务，结果未知时应查询、核对或等待人工处理，不能盲目重发。该设计原则是本项目综合，不是Redis提供跨系统恰好一次保证。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-idempotency","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://redis.io/docs/latest/commands/xreadgroup/","source_version":"Redis rolling command reference; checked 2026-10-20","tags":["幂等","idempotency","request_id","回执","超时"],"technical_doc_id":null,"title":"外部超时与幂等回执","updated_at":"2026-10-20"}','98ecb016acfef596ca7c8d7d9f0737df8696ef3ff9af6ad9ce0f523ab64e0278','56cd4ef6cec1b52dbd118702a08631425912eac035d82a1075c2b1fda71af865');
INSERT INTO "v3_public_versions" VALUES('knowledge-5a7d50cf2863660d959f4d317523b8e6ead83f588442d26261be7a54c10c2152','doc-provenance','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"检索用于在查询时提供相关外部上下文，减少一次性塞入全部材料的需求。相关片段本身不是事实支持判定。本项目把公共技术解释、私人源码和个人自述分域处理：公共资料不能证明用户有该技能，代码只能定位某版实现，自述仍需核实。缺证据应表达不确定或请求补充，不能推断用户没有能力。该事实分级是本项目约束。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-provenance","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://docs.langchain.com/oss/python/deepagents/retrieval","source_version":"Retrieval rolling documentation; checked 2026-10-20","tags":["RAG","证据","来源","支持","相关性"],"technical_doc_id":null,"title":"检索相关性与事实支持","updated_at":"2026-10-20"}','5a7d50cf2863660d959f4d317523b8e6ead83f588442d26261be7a54c10c2152','834bf21a5648d31399314077bc22d70e5b9b4d12ebacfc17e429ec044532d70b');
INSERT INTO "v3_public_versions" VALUES('knowledge-f71edafd7d966bf815f2b96136b178973e8a0cf88495e621f867357964a21836','doc-rrf','{"aliases":[],"answer_points":[],"applicable_role":"AI Agent / Python后端实习","body":"关键词召回适合准确术语，向量召回用于语义相近表达。不同检索器分数尺度通常不能直接相加，RRF按排名倒数贡献融合；参数和候选深度会影响结果。融合后仍要去重并验证引用。是否保留向量或重排，应在相同查询与标注下比较召回、成本和失败，不预设更复杂一定更好。本项目没有因此部署Elasticsearch。","content_basis":"project_authored_summary_not_official_quote","difficulty":"intermediate","entry_id":"doc-rrf","followups":[],"kind":"doc","license":"CC0-1.0","source_url":"https://www.elastic.co/docs/reference/elasticsearch/rest-apis/reciprocal-rank-fusion","source_version":"Elasticsearch rolling reference; checked 2026-10-20","tags":["BM25","RRF","hybrid","检索","融合"],"technical_doc_id":null,"title":"关键词、向量与RRF融合","updated_at":"2026-10-20"}','f71edafd7d966bf815f2b96136b178973e8a0cf88495e621f867357964a21836','bdb5762688d1531278c26d727fbb890fbfce9e05f3f5e27c98a3833150bcbb4b');
